import{z as B,x as p,o as e,c as A,q as o,j as l,D as r,d as n,s,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"平面图算法","description":"","frontmatter":{"title":"平面图算法","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/planar-algorithms.md","filePath":"cs/planar-algorithms.md","lastUpdated":1791063341000}'),d={name:"cs/planar-algorithms.md"};function m(h,a,D,u,c,C){const t=p("Mermaid");return e(),A("div",null,[a[2]||(a[2]=o('<h1 id="平面图算法" tabindex="-1">平面图算法 <a class="header-anchor" href="#平面图算法" aria-label="Permalink to &quot;平面图算法&quot;">​</a></h1><div class="epigraph"><p>平面图 $E=O(V)$，有线性分离器；许多 NPC 问题在平面上仍难，但分离器给了亚指数精确与更快的最短路。</p><footer>—— 据 Kuratowski, 1930；Lipton and Tarjan, A Separator Theorem for Planar Graphs, 1979；四色见 Appel and Haken, 1977 整理</footer></div><p>上一课<a href="/cs/graph-coloring">图着色与启发</a>在一般图。平面图：\\(K_5\\)、\\(K_{3,3}\\) 的细分禁止（Kuratowski）。四色 \\(\\chi\\le 4\\)。本课不重证四色。缺口是<strong>算法后果</strong>：欧拉公式导出稀疏；\\(O(\\sqrt n)\\) 分离器；最短路、独立集等因此更快或可分治。后课图同构直觉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>嵌入平面则 \\(E\\le 3V-6\\)（\\(V\\ge 3\\)，简单）。对偶图：面当点，边相交当相邻。平面分离器：可在 \\(O(n)\\) 找到大小 \\(O(\\sqrt n)\\) 的点集，删后每块 \\(\\le 2n/3\\)。分治：子问题规模降，加上跨越分离器的枚举。独立集、哈密顿在平面上仍 NPC，但 \\(2^{O(\\sqrt n)}\\) 精确成为可能。</p><p>缺口是稀疏与分离，不是画图美学。</p><h3 id="四色不是线性时间着色课的主定理" tabindex="-1">四色不是线性时间着色课的主定理 <a class="header-anchor" href="#四色不是线性时间着色课的主定理" aria-label="Permalink to &quot;四色不是线性时间着色课的主定理&quot;">​</a></h3><p>四色存在；求 5-着色有线性/近线性算法（线性时间 5-着色经典）。四色的证明是计算机验证个案，本课当黑盒：\\(\\chi\\le 4\\)。6-着色由 degeneracy \\(\\le 5\\) 立即得到。</p><p><span class="marginnote">Lipton–Tarjan 1979 分离器。Hopcroft–Tarjan 平面性线性判定。后课同构：平面图同构曾更早有多项式，一般图更晚。</span></p><p><span class="marginnote">数字实例：\\(V=1000\\) 个点的平面图，边数至多 \\(3\\times1000-6=2994\\) 条；一般图却可以有 \\(1000\\times999/2\\approx 50\\) 万条。「一张地图的路天然只有几千条」正是平面算法跑得快的本钱。</span></p><p><span class="marginnote">常见误区：以为「我画出来不交叉」就算给了算法一个平面嵌入。算法拿到的通常只是邻接表，有没有交叉它并不知道——得先跑线性时间的平面性判定拿到嵌入，分离器才有的下手。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>平面性：左–右/PQ 树或 Hopcroft–Tarjan，\\(O(n)\\)。最短路：稀疏图 Dijkstra \\(O(n\\log n)\\)；更细的平面最短路（Henzinger 等）点名。分离器递归解 NP 子集问题。</p>',13)),(e(),l(i,null,{default:r(()=>[s(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PL%5B%22%E5%B9%B3%E9%9D%A2%E5%B5%8C%E5%85%A5%22%5D%20--%3E%20SP%5B%22E%3DO(V)%20%E7%A8%80%E7%96%8F%22%5D%0A%20%20PL%20--%3E%20SEP%5B%22O(%E2%88%9An)%20%E5%88%86%E7%A6%BB%E5%99%A8%22%5D%0A%20%20SEP%20--%3E%20DC%5B%22%E5%88%86%E6%B2%BB%E7%B2%BE%E7%A1%AE%20%2F%20%E5%8A%A0%E9%80%9F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"最大流在平面 \\(s\\)–\\(t\\) 可用对偶最短路，点名。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"欧拉 \\(V-E+F=2\\) 加每面至少 3 边推出稀疏。分离器来自平面网格式的等周：最短路树或 BFS 层切。与一般图：扩展图没有小分离器，点分治式的亚指数失败。不要把「画在纸上不交叉」当算法已给嵌入——先判定平面性。",-1)),a[6]||(a[6]=E("p",null,"分离器分治到底怎么把答案「拼」出来？",-1)),(e(),l(i,null,{default:r(()=>[s(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E8%A7%84%E6%A8%A1%20n%20%E7%9A%84%E5%B9%B3%E9%9D%A2%E9%97%AE%E9%A2%98%22%5D%20--%3E%20S%5B%22%E8%8A%B1%20O%20%E7%BA%BF%E6%80%A7%E6%97%B6%E9%97%B4%E6%89%BE%E5%88%86%E7%A6%BB%E5%99%A8%20S%EF%BC%8C%E7%BA%A6%E6%A0%B9%E5%8F%B7%20n%20%E4%B8%AA%E7%82%B9%22%5D%0A%20%20S%20--%3E%20CUT%5B%22%E5%88%A0%E6%8E%89%20S%EF%BC%8C%E5%9B%BE%E8%A3%82%E6%88%90%E5%87%A0%E5%9D%97%22%5D%0A%20%20CUT%20--%3E%20A%5B%22%E5%9D%97%201%EF%BC%9A%E4%B8%8D%E8%B6%85%E8%BF%87%202n%2F3%22%5D%0A%20%20CUT%20--%3E%20B%5B%22%E5%9D%97%202%EF%BC%9A%E4%B8%8D%E8%B6%85%E8%BF%87%202n%2F3%22%5D%0A%20%20A%20--%3E%20REC%5B%22%E5%AF%B9%E6%AF%8F%E5%9D%97%E9%80%92%E5%BD%92%E5%90%8C%E4%B8%80%E5%A5%97%22%5D%0A%20%20B%20--%3E%20REC%0A%20%20S%20--%3E%20ENUM%5B%22%E5%8F%AA%E6%9E%9A%E4%B8%BE%20S%20%E4%B8%8A%E5%B0%91%E6%95%B0%E7%82%B9%E7%9A%84%E5%8F%96%E8%88%8D%E7%BB%84%E5%90%88%22%5D%0A%20%20REC%20--%3E%20COMB%5B%22%E5%9D%97%E5%86%85%E7%AD%94%E6%A1%88%E4%B8%8E%E6%9E%9A%E4%B8%BE%E7%BB%93%E6%9E%9C%E6%8B%BC%E5%90%88%22%5D%0A%20%20ENUM%20--%3E%20COMB%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">直觉类比：把地图沿一条环线切开，环线经过的点不多（约根号 \\(n\\) 个），但两侧各自不超过全图的三分之二。分治时只需枚举环线上少数点的取舍，两边内部各算各的，最后拼账。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Robertson–Seymour 浅，不写曲面亏格全文。不进光刻掩模几何。后课默认：平面 \\(\\Rightarrow\\) 稀疏 + 分离器；四色当事实。下一课图同构的直觉与算法地位。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>平面稀疏；Kuratowski 禁 \\(K_5\\)、\\(K_{3,3}\\)。</li><li>Lipton–Tarjan 分离器支撑分治。</li><li>许多问题仍 NPC，但指数底可变。</li><li>出处：Kuratowski, 1930；Lipton and Tarjan, 1979；Appel and Haken, 1977。</li></ul>',5))])}const _=B(d,[["render",m]]);export{T as __pageData,_ as default};
